        Question(21214, "Quel pays est le plus grand consommateur de bière par habitant ?", listOf("La République tchèque", "L'Allemagne", "La Belgique", "L'Irlande"), 0, "Gastronomie", Difficulty.HARD, explanation = "La République tchèque détient ce record depuis des années, avec une consommation moyenne de plus de 140 litres par habitant et par an, notamment grâce à la culture de la bière blonde comme la Pilsner."),
        Question(21215, "Quel est l'ingrédient de base de la polenta ?", listOf("La semoule de maïs", "La farine de blé", "Le riz", "L'orge"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La polenta est un plat traditionnel italien à base de farine ou de semoule de maïs cuite dans de l'eau ou du bouillon."),
        Question(21216, "Quel champignon est le plus recherché en gastronomie française ?", listOf("La truffe noire", "Le cèpe", "La morille", "La chanterelle"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La truffe noire, ou Tuber melanosporum, est prisée pour son arôme puissant et sa rareté, ce qui en fait un ingrédient de luxe dans la cuisine française."),
        Question(21217, "D'où vient le chocolat à l'origine ?", listOf("D'Amérique centrale (Mexique)", "D'Afrique", "D'Asie", "D'Europe"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le cacaoyer est originaire d'Amérique centrale, où les civilisations maya et aztèque cultivaient déjà le cacao pour préparer une boisson amère, bien avant l'arrivée des Européens."),
        Question(21218, "Quel alcool est distillé à partir de la canne à sucre ?", listOf("Le rhum", "La vodka", "Le whisky", "Le gin"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le rhum est produit par distillation du jus de canne à sucre ou de ses sous-produits, comme la mélasse."),
        Question(21219, "Combien de régions viticoles la France compte-t-elle environ ?", listOf("17", "10", "25", "8"), 0, "Gastronomie", Difficulty.HARD, explanation = "La France compte officiellement 17 régions viticoles, incluant des zones comme Bordeaux, Bourgogne ou Champagne, qui structurent son paysage viticole."),
        Question(21220, "Quel plat japonais est fait de riz vinaigré et de poisson cru ?", listOf("Le sushi", "Le ramen", "Le tempura", "Le gyoza"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le sushi associe du riz vinaigré à du poisson cru, une combinaison emblématique de la cuisine japonaise."),
        Question(21221, "Quel pays a inventé la pizza ?", listOf("L'Italie", "La Grèce", "Les États-Unis", "La Turquie"), 0, "Gastronomie", Difficulty.EASY, explanation = "La pizza moderne, telle qu'on la connaît aujourd'hui avec la tomate et la mozzarella, est née à Naples, en Italie, au 18e siècle."),
        Question(21222, "Qu'est-ce que le wasabi véritable ?", listOf("Une racine de la famille du raifort", "Un algue", "Un piment", "Un champignon"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le wasabi véritable est fabriqué à partir de la racine d'Eutrema japonicum, une plante de la famille du raifort, contrairement aux pâtes vertes imitant le wasabi."),
        Question(21223, "Quel est le fromage le plus consommé au monde ?", listOf("La mozzarella", "Le cheddar", "Le camembert", "Le gruyère"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La mozzarella est le fromage le plus consommé au monde grâce à son utilisation massive sur les pizzas, un plat populaire à l'échelle planétaire."),
        Question(21224, "Quel plat thaïlandais est une soupe épicée aux crevettes ?", listOf("Tom Yam Kung", "Pad Thaï", "Som Tam", "Massaman Curry"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Tom Yam Kung est une soupe emblématique de la Thaïlande, reconnaissable à son bouillon épicé et aigre à base de crevettes, de citronnelle et de galanga."),
        Question(21225, "Quel vin effervescent ne peut s'appeler 'Champagne' que s'il vient de Champagne ?", listOf("Le Champagne (AOC protégée)", "Le Prosecco", "Le Cava", "Le Crémant"), 0, "Gastronomie", Difficulty.EASY, explanation = "L'appellation Champagne est protégée par une AOC (Appellation d'Origine Contrôlée) qui réserve ce nom aux vins effervescents produits dans la région de Champagne, en France."),
        Question(21226, "Quel fruit est à la base du ketchup ?", listOf("La tomate", "Le poivron", "La betterave", "La cerise"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le ketchup moderne est principalement fabriqué à partir de tomates, bien que les premières versions chinoises utilisaient une saumure de poisson. La recette à base de tomates s'est popularisée aux États-Unis au XIXe siècle."),
        Question(21227, "Quelle cuisine utilise beaucoup le lait de coco ?", listOf("La cuisine thaïlandaise", "La cuisine japonaise", "La cuisine italienne", "La cuisine mexicaine"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le lait de coco est un ingrédient fondamental de la cuisine thaïlandaise, utilisé dans de nombreux plats comme les currys et les soupes pour sa texture crémeuse et sa saveur douce."),
        Question(21228, "Qu'est-ce que la cuisine moléculaire ?", listOf("L'application de la science à la cuisine", "La cuisine au micro-ondes", "La cuisine végétarienne", "La cuisine industrielle"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La cuisine moléculaire utilise des principes scientifiques comme les réactions chimiques et physiques pour transformer les textures et les saveurs des aliments."),
        Question(21229, "Quel pain est typique de la cuisine indienne ?", listOf("Le naan", "La baguette", "Le pain pita", "La tortilla"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le naan est un pain plat levé, cuit traditionnellement dans un four tandoor, et il accompagne fréquemment les currys et plats en sauce en Inde."),
        Question(21230, "Combien d'étoiles maximum un restaurant peut-il recevoir au Guide Michelin ?", listOf("3", "4", "5", "2"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le Guide Michelin attribue un maximum de trois étoiles, symbole d'une cuisine exceptionnelle qui vaut le détour. C'est la plus haute distinction possible pour un restaurant.")
    )

    // ===== GÉOGRAPHIE — 30 questions =====
    private fun geographie(): List<Question> = listOf(
        Question(21303, "Combien de continents y a-t-il ?", listOf("7", "5", "6", "8"), 0, "Géographie", Difficulty.EASY, explanation = "Le modèle des sept continents (Afrique, Amérique, Antarctique, Asie, Europe, Océanie) est le plus enseigné dans les pays francophones."),
        Question(21304, "Quelle est la plus haute montagne du monde ?", listOf("L'Everest", "Le K2", "Le Kangchenjunga", "Le Mont Blanc"), 0, "Géographie", Difficulty.EASY, explanation = "L'Everest, culminant à 8 848 mètres, est le sommet le plus élevé de la planète, situé dans la chaîne de l'Himalaya, à la frontière du Népal et du Tibet."),
        Question(21305, "Quel détroit sépare l'Europe de l'Afrique ?", listOf("Le détroit de Gibraltar", "Le Bosphore", "Le détroit de Messine", "Le détroit d'Ormuz"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit de Gibraltar relie la mer Méditerranée à l'océan Atlantique, séparant l'Espagne au nord du Maroc au sud."),
        Question(21306, "Quelle est la ville la plus peuplée du monde ?", listOf("Tokyo", "Shanghai", "New York", "São Paulo"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Tokyo est l'agglomération la plus peuplée du monde avec environ 37 millions d'habitants, dépassant largement les autres grandes métropoles comme Delhi ou Shanghai."),
        Question(21307, "Dans quel océan se trouve Madagascar ?", listOf("L'océan Indien", "L'océan Atlantique", "L'océan Pacifique", "L'océan Arctique"), 0, "Géographie", Difficulty.EASY, explanation = "Madagascar est une île située dans l'océan Indien, au large de la côte sud-est de l'Afrique."),
        Question(21309, "Quel pays a la plus grande superficie en Afrique ?", listOf("L'Algérie", "Le Congo", "Le Soudan", "La Libye"), 0, "Géographie", Difficulty.HARD, explanation = "Depuis le partition du Soudan en 2011, l'Algérie est le plus vaste pays d'Afrique avec une superficie de près de 2,38 millions de km²."),
        Question(21310, "Quelle mer est la plus salée du monde ?", listOf("La mer Morte", "La mer Rouge", "La mer Caspienne", "La mer Méditerranée"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La mer Morte est la plus salée du monde en raison de son taux de salinité extrêmement élevé, environ 34 %, dû à une forte évaporation et à l'absence d'exutoire."),
        Question(21311, "Quel pays est traversé par le plus grand nombre de fuseaux horaires ?", listOf("La France (12 fuseaux, outre-mer)", "La Russie (11)", "Les États-Unis (6)", "Le Canada (6)"), 0, "Géographie", Difficulty.EXPERT, explanation = "La France possède 12 fuseaux horaires grâce à ses territoires d'outre-mer dispersés dans l'océan Pacifique, l'océan Indien et l'Atlantique."),
        Question(21314, "Sur quel continent se trouve le Kilimandjaro ?", listOf("L'Afrique", "L'Asie", "L'Amérique du Sud", "L'Europe"), 0, "Géographie", Difficulty.EASY, explanation = "Le Kilimandjaro est le plus haut sommet d'Afrique, culminant à 5 895 mètres, et il est situé en Tanzanie, dans l'est du continent africain."),
        Question(21315, "Quel fleuve traverse Paris ?", listOf("La Seine", "La Loire", "Le Rhône", "La Garonne"), 0, "Géographie", Difficulty.EASY, explanation = "La Seine traverse Paris en formant un large méandre qui divise la ville en rive droite et rive gauche."),
        Question(21317, "Quel pays est surnommé 'le pays du Soleil-Levant' ?", listOf("Le Japon", "La Chine", "La Corée du Sud", "La Thaïlande"), 0, "Géographie", Difficulty.EASY, explanation = "Le Japon est surnommé le pays du Soleil-Levant car il est situé à l'est de l'Asie, et son nom en japonais, Nihon, signifie littéralement origine du soleil."),
        Question(21319, "Quel pays est en forme de botte ?", listOf("L'Italie", "La Grèce", "Le Portugal", "La Croatie"), 0, "Géographie", Difficulty.EASY, explanation = "La péninsule italienne s'étend dans la mer Méditerranée, et sa forme évoque une botte, avec le talon correspondant aux Pouilles et la pointe à la Calabre."),
        Question(21321, "Quel est le point le plus bas de la Terre ?", listOf("La mer Morte (-430m)", "La fosse des Mariannes", "Le lac Assal", "Death Valley"), 0, "Géographie", Difficulty.HARD, explanation = "La mer Morte, située entre Israël, la Jordanie et la Cisjordanie, est le point le plus bas de la surface terrestre avec une altitude de -430 mètres."),
        Question(21322, "Quelle île est la plus grande du monde ?", listOf("Le Groenland", "Madagascar", "Bornéo", "La Nouvelle-Guinée"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le Groenland est une vaste île située dans l'océan Atlantique Nord, territoire autonome du Danemark, dont la superficie de 2,16 millions de km² en fait la plus grande île non continentale du monde."),
        Question(21324, "Combien de pays l'Afrique compte-t-elle ?", listOf("54", "48", "60", "45"), 0, "Géographie", Difficulty.MEDIUM, explanation = "L'Union africaine reconnaît officiellement 54 États souverains sur le continent, incluant des pays comme le Nigeria et l'Égypte, mais excluant le Sahara occidental (territoire disputé)."),
        Question(21325, "Quel pays partage la plus longue frontière terrestre avec la France métropolitaine ?", listOf("L'Espagne", "La Belgique", "L'Italie", "L'Allemagne"), 0, "Géographie", Difficulty.HARD, explanation = "La France métropolitaine partage sa plus longue frontière terrestre avec l'Espagne, longue de 623 km le long des Pyrénées."),
        Question(21327, "Quel pays est un archipel de 17 000 îles ?", listOf("L'Indonésie", "Les Philippines", "Le Japon", "La Grèce"), 0, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand archipel du monde, composé d'environ 17 000 îles, dont les principales sont Java, Sumatra, Bornéo, Sulawesi et la Nouvelle-Guinée."),
        Question(21328, "Où se trouve le canal de Suez ?", listOf("En Égypte", "Au Panama", "En Turquie", "Au Maroc"), 0, "Géographie", Difficulty.EASY, explanation = "Le canal de Suez relie la mer Méditerranée à la mer Rouge, et il traverse entièrement le territoire égyptien."),
        Question(21329, "Quelle ville est surnommée 'la Ville éternelle' ?", listOf("Rome", "Athènes", "Paris", "Istanbul"), 0, "Géographie", Difficulty.EASY, explanation = "Rome est surnommée la Ville éternelle en raison de sa longévité historique et de son influence durable sur la civilisation occidentale, un titre qui remonte à l'Antiquité romaine."),
        Question(21330, "Quel pays a le plus d'habitants au monde ?", listOf("L'Inde", "La Chine", "Les États-Unis", "L'Indonésie"), 0, "Géographie", Difficulty.EASY, explanation = "L'Inde a dépassé la Chine en 2023 pour devenir le pays le plus peuplé du monde, avec environ 1,4 milliard d'habitants.")
    )

    // ===== TECH — 25 questions =====
    private fun tech(): List<Question> = listOf(
        Question(21401, "Quel langage de programmation est surnommé le 'langage du web' ?", listOf("JavaScript", "Python", "Java", "C++"), 0, "Tech", Difficulty.EASY, explanation = "JavaScript est le langage de programmation principalement utilisé pour rendre les pages web interactives, d'où son surnom de \"langage du web\". Il est exécuté par les navigateurs et permet des fonctionnalités dynamiques comme les animations et les formulaires."),
        Question(21403, "Que signifie 'IA' ?", listOf("Intelligence Artificielle", "Interface Automatique", "Informatique Avancée", "Intégration Applicative"), 0, "Tech", Difficulty.EASY, explanation = "L'acronyme IA désigne l'Intelligence Artificielle, un domaine de l'informatique visant à créer des systèmes capables de simuler des capacités cognitives humaines."),
        Question(21404, "En quelle année le premier iPhone est-il sorti ?", listOf("2007", "2005", "2009", "2010"), 0, "Tech", Difficulty.MEDIUM, explanation = "Le premier iPhone a été présenté par Steve Jobs le 9 janvier 2007 et mis en vente aux États-Unis le 29 juin de la même année."),
        Question(21405, "Quel protocole est utilisé pour les pages web sécurisées ?", listOf("HTTPS", "FTP", "SSH", "SMTP"), 0, "Tech", Difficulty.MEDIUM, explanation = "HTTPS (HyperText Transfer Protocol Secure) chiffre les données échangées entre le navigateur et le serveur via TLS/SSL, contrairement au HTTP non sécurisé."),
        Question(21407, "Quel est le système d'exploitation mobile le plus utilisé ?", listOf("Android", "iOS", "Windows Phone", "HarmonyOS"), 0, "Tech", Difficulty.EASY, explanation = "Android domine le marché mondial des smartphones avec plus de 70 % de parts, grâce à son adoption par de nombreux fabricants comme Samsung et Xiaomi."),
        Question(21408, "Que signifie l'acronyme 'CPU' ?", listOf("Central Processing Unit", "Computer Power Unit", "Central Program Utility", "Core Process Unit"), 0, "Tech", Difficulty.MEDIUM, explanation = "Le CPU, ou Central Processing Unit, est le composant principal d'un ordinateur qui exécute les instructions des programmes. Il est souvent appelé le \"cerveau\" de la machine."),
        Question(21409, "Quel réseau social a été fondé par Mark Zuckerberg ?", listOf("Facebook", "Twitter", "LinkedIn", "Instagram"), 0, "Tech", Difficulty.EASY, explanation = "Mark Zuckerberg a cofondé Facebook en 2004 avec ses camarades de l'université Harvard, Eduardo Saverin, Andrew McCollum, Dustin Moskovitz et Chris Hughes."),
        Question(21411, "Quel algorithme est utilisé pour le chiffrement asymétrique ?", listOf("RSA", "AES", "SHA-256", "MD5"), 0, "Tech", Difficulty.HARD, explanation = "RSA est un algorithme de chiffrement asymétrique reposant sur la difficulté de factoriser de grands nombres premiers, largement utilisé pour sécuriser les communications en ligne."),
        Question(21413, "Qu'est-ce qu'un API ?", listOf("Application Programming Interface", "Automated Process Integration", "Advanced Protocol Internet", "Application Port Identifier"), 0, "Tech", Difficulty.MEDIUM, explanation = "Une API est un ensemble de règles et de protocoles qui permet à deux applications logicielles de communiquer entre elles, facilitant l'échange de données et de fonctionnalités."),
        Question(21414, "Quel langage est utilisé pour le machine learning ?", listOf("Python", "HTML", "CSS", "SQL"), 0, "Tech", Difficulty.EASY, explanation = "Python est le langage le plus utilisé en machine learning grâce à ses bibliothèques spécialisées comme TensorFlow, PyTorch et scikit-learn, qui simplifient la création et l'entraînement de modèles."),
        Question(21415, "Combien de bits dans un octet ?", listOf("8", "4", "16", "32"), 0, "Tech", Difficulty.EASY, explanation = "Un octet est une unité de mesure informatique standard composée de 8 bits, permettant de représenter 256 valeurs différentes (de 0 à 255)."),
        Question(21417, "Quel composant stocke les données de manière permanente ?", listOf("Le disque dur (SSD/HDD)", "La RAM", "Le CPU", "La carte graphique"), 0, "Tech", Difficulty.EASY, explanation = "Contrairement à la mémoire vive (RAM), le disque dur (SSD ou HDD) conserve les données même après l'extinction de l'ordinateur, servant de stockage permanent pour le système d'exploitation et les fichiers."),
        Question(21419, "Quel est le langage principal des bases de données relationnelles ?", listOf("SQL", "Python", "Java", "R"), 0, "Tech", Difficulty.MEDIUM, explanation = "SQL (Structured Query Language) est le langage standard utilisé pour interroger, manipuler et gérer les données dans les bases de données relationnelles."),
        Question(21420, "Qu'est-ce qu'un conteneur Docker ?", listOf("Un environnement isolé pour exécuter des applications", "Un type de serveur", "Un protocole réseau", "Un langage de programmation"), 0, "Tech", Difficulty.HARD, explanation = "Docker utilise des conteneurs pour encapsuler une application et ses dépendances, garantissant qu'elle fonctionne de manière cohérente dans n'importe quel environnement."),
        Question(21421, "Quel est le principe du modèle TCP/IP ?", listOf("Découper les données en paquets pour les transmettre", "Chiffrer les données", "Compresser les fichiers", "Accélérer le processeur"), 0, "Tech", Difficulty.HARD, explanation = "Le modèle TCP/IP fragmente les données en paquets pour optimiser leur acheminement sur les réseaux, chaque paquet pouvant emprunter un chemin différent jusqu'à la destination."),
        Question(21422, "Quelle entreprise a créé ChatGPT ?", listOf("OpenAI", "Google", "Meta", "Microsoft"), 0, "Tech", Difficulty.EASY, explanation = "OpenAI a développé ChatGPT, un modèle de langage basé sur l'intelligence artificielle, lancé en novembre 2022. L'entreprise a été fondée en 2015 avec une mission de recherche en IA bénéfique."),
        Question(21424, "Quel est le rôle d'un pare-feu (firewall) ?", listOf("Filtrer le trafic réseau entrant et sortant", "Accélérer Internet", "Stocker les mots de passe", "Compresser les données"), 0, "Tech", Difficulty.MEDIUM, explanation = "Le pare-feu agit comme une barrière de sécurité en analysant les paquets de données pour bloquer les accès non autorisés tout en autorisant les communications légitimes."),
        Question(21425, "Qu'est-ce que la loi de Moore ?", listOf("Le nombre de transistors double tous les ~2 ans", "La vitesse d'Internet double chaque année", "Le prix du stockage baisse de moitié", "La RAM double tous les 5 ans"), 0, "Tech", Difficulty.HARD, explanation = "Énoncée en 1965 par Gordon Moore, cofondateur d'Intel, cette observation prédisait que la densité des transistors sur une puce doublerait environ tous les deux ans, ce qui a guidé l'innovation technologique pendant des décennies.")
    )

    // ===== SCIENCE — 25 questions =====
    private fun science(): List<Question> = listOf(
        Question(21501, "Quel est l'état de la matière du plasma ?", listOf("Gaz ionisé (4ème état)", "Liquide dense", "Solide chauffé", "Gaz refroidi"), 0, "Science", Difficulty.HARD, explanation = "Le plasma est un gaz dont les atomes ont été ionisés, perdant ou gagnant des électrons, ce qui le rend conducteur d'électricité et sensible aux champs magnétiques."),
        Question(21502, "Qu'est-ce que l'ADN ?", listOf("Acide désoxyribonucléique", "Acide dinitrique", "Amine dérivée naturelle", "Agent de neutralisation"), 0, "Science", Difficulty.EASY, explanation = "L'ADN est l'abréviation d'acide désoxyribonucléique, la molécule qui porte l'information génétique dans toutes les cellules vivantes."),
        Question(21503, "Quel est le métal le plus conducteur d'électricité ?", listOf("L'argent", "Le cuivre", "L'or", "L'aluminium"), 0, "Science", Difficulty.HARD, explanation = "L'argent possède la plus haute conductivité électrique de tous les métaux à température ambiante, grâce à sa structure atomique qui permet une circulation très libre des électrons."),
        Question(21505, "Quelle est la couche protectrice de l'atmosphère contre les UV ?", listOf("La couche d'ozone", "La troposphère", "La mésosphère", "La thermosphère"), 0, "Science", Difficulty.EASY, explanation = "La couche d'ozone, située dans la stratosphère, absorbe la majeure partie des rayons ultraviolets (UV) nocifs du Soleil."),
        Question(21506, "Quel est le nombre d'Avogadro ?", listOf("6,022 × 10²³", "3,14159", "2,718", "9,81"), 0, "Science", Difficulty.HARD, explanation = "Ce nombre correspond au nombre d'entités élémentaires (atomes, molécules, ions) contenues dans une mole d'une substance, une constante fondamentale en chimie."),
        Question(21508, "Quel organe filtre le sang ?", listOf("Les reins", "Le foie", "Le cœur", "Les poumons"), 0, "Science", Difficulty.EASY, explanation = "Les reins filtrent les déchets et l'excès d'eau du sang pour produire l'urine, jouant un rôle clé dans l'équilibre hydrique et l'élimination des toxines."),
        Question(21509, "Qu'est-ce que la théorie des cordes ?", listOf("Les particules fondamentales sont des cordes vibrantes", "Les planètes sont reliées par des cordes gravitationnelles", "La lumière est composée de filaments", "Les atomes sont liés par des fils"), 0, "Science", Difficulty.EXPERT, explanation = "La théorie des cordes postule que les particules élémentaires ne sont pas des points, mais des cordes unidimensionnelles dont les modes de vibration déterminent leurs propriétés."),
        Question(21510, "Quel est le gaz noble le plus léger ?", listOf("L'hélium", "Le néon", "L'argon", "Le krypton"), 0, "Science", Difficulty.MEDIUM, explanation = "L'hélium est le gaz noble le plus léger car il possède la plus faible masse atomique parmi les gaz rares, avec seulement deux protons et deux neutrons dans son noyau."),
        Question(21511, "Combien de paires de bases composent le génome humain ?", listOf("3 milliards", "1 million", "10 milliards", "100 millions"), 0, "Science", Difficulty.HARD, explanation = "Le génome humain est constitué d'environ 3 milliards de paires de bases d'ADN, réparties sur 23 paires de chromosomes."),
        Question(21513, "Quel élément chimique a pour symbole 'Na' ?", listOf("Le sodium", "L'azote", "Le nickel", "Le néon"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole Na vient du latin *natrium*. Le sodium est un métal alcalin très réactif, notamment avec l'eau."),
        Question(21514, "Qu'est-ce que la supraconductivité ?", listOf("Résistance électrique nulle à très basse température", "Conductivité très élevée", "Un type d'aimant", "La vitesse maximale d'un courant"), 0, "Science", Difficulty.EXPERT, explanation = "Découverte en 1911 par Heike Kamerlingh Onnes, la supraconductivité se produit dans certains matériaux refroidis sous une température critique, où les électrons se déplacent sans perte d'énergie."),
        Question(21517, "Quel virus cause le SIDA ?", listOf("Le VIH", "Le VHC", "Le VPH", "Le VRS"), 0, "Science", Difficulty.EASY, explanation = "Le VIH (virus de l'immunodéficience humaine) attaque le système immunitaire, et sans traitement, il peut évoluer vers le SIDA (syndrome d'immunodéficience acquise)."),
        Question(21518, "Combien de temps la lumière du Soleil met-elle pour atteindre la Terre ?", listOf("~8 minutes", "~1 seconde", "~30 minutes", "~1 heure"), 0, "Science", Difficulty.MEDIUM, explanation = "La lumière du Soleil parcourt environ 150 millions de kilomètres à la vitesse de 300 000 km/s, ce qui prend environ 8 minutes et 20 secondes pour atteindre la Terre."),
        Question(21519, "Qu'est-ce que CRISPR-Cas9 ?", listOf("Un outil d'édition génétique", "Un télescope spatial", "Un accélérateur de particules", "Un médicament anticancer"), 0, "Science", Difficulty.HARD, explanation = "CRISPR-Cas9 est une technologie dérivée d’un système de défense bactérien, permettant de modifier précisément l’ADN d’organismes vivants."),
        Question(21520, "Quel est le point de congélation de l'eau en Kelvin ?", listOf("273,15 K", "0 K", "100 K", "373 K"), 0, "Science", Difficulty.HARD, explanation = "L'eau pure gèle à 0°C, ce qui correspond à 273,15 Kelvin, car le zéro absolu (0 K) est à -273,15°C."),
        Question(21521, "Qu'est-ce qu'un neutron star (étoile à neutrons) ?", listOf("Le résidu ultra-dense d'une supernova", "Une étoile sans charge", "Un type de trou noir", "Une planète gazeuse"), 0, "Science", Difficulty.HARD, explanation = "Lorsqu'une étoile massive explose en supernova, son noyau s'effondre sous l'effet de la gravité, formant un objet extrêmement dense composé presque uniquement de neutrons."),
        Question(21523, "Qu'est-ce que la photosynthèse produit ?", listOf("Du glucose et de l'oxygène", "Du CO2 et de l'eau", "De l'azote", "Du méthane"), 0, "Science", Difficulty.EASY, explanation = "La photosynthèse utilise l'énergie solaire pour convertir le dioxyde de carbone et l'eau en glucose (source d'énergie pour la plante) et en oxygène, libéré dans l'atmosphère."),
        Question(21524, "Quel scientifique a découvert la radioactivité ?", listOf("Henri Becquerel", "Marie Curie", "Ernest Rutherford", "Wilhelm Röntgen"), 0, "Science", Difficulty.HARD, explanation = "Henri Becquerel a découvert la radioactivité en 1896 par hasard, en observant que des sels d'uranium impressionnaient des plaques photographiques sans exposition à la lumière."),
        Question(21525, "Combien d'états de la matière existe-t-il principalement ?", listOf("4 (solide, liquide, gaz, plasma)", "3", "5", "2"), 0, "Science", Difficulty.MEDIUM, explanation = "Les quatre états principaux de la matière sont le solide, le liquide, le gaz et le plasma, ce dernier étant un gaz ionisé présent notamment dans les étoiles.")
    )

    // ===== HISTOIRE — 25 questions =====
    private fun histoire(): List<Question> = listOf(
        Question(21601, "En quelle année a débuté la Première Guerre mondiale ?", listOf("1914", "1912", "1916", "1918"), 0, "Histoire", Difficulty.EASY, explanation = "La Première Guerre mondiale a débuté en 1914 après l'assassinat de l'archiduc François-Ferdinand d'Autriche en juin, suivi d'une série de déclarations de guerre en août."),
        Question(21604, "En quelle année l'esclavage a-t-il été aboli en France ?", listOf("1848", "1794", "1833", "1865"), 0, "Histoire", Difficulty.HARD, explanation = "L'abolition définitive de l'esclavage en France a été proclamée le 27 avril 1848, sous l'impulsion du gouvernement provisoire de la Deuxième République, notamment grâce à l'action de Victor Schœlcher."),
        Question(21606, "Quel empire a construit le Colisée de Rome ?", listOf("L'Empire romain", "L'Empire grec", "L'Empire perse", "L'Empire byzantin"), 0, "Histoire", Difficulty.EASY, explanation = "Le Colisée de Rome a été construit sous l'Empire romain, entre 70 et 80 après J.-C., par les empereurs Vespasien et Titus de la dynastie flavienne."),
        Question(21607, "En quelle année a eu lieu le débarquement en Normandie ?", listOf("1944", "1943", "1945", "1942"), 0, "Histoire", Difficulty.EASY, explanation = "Le débarquement en Normandie, nom de code opération Overlord, a eu lieu le 6 juin 1944, marquant le début de la libération de l'Europe occidentale occupée par l'Allemagne nazie pendant la Seconde Guerre mondiale."),
        Question(21608, "Qui a peint le plafond de la chapelle Sixtine ?", listOf("Michel-Ange", "Raphaël", "Léonard de Vinci", "Botticelli"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Michel-Ange a peint le plafond de la chapelle Sixtine entre 1508 et 1512, sur commande du pape Jules II."),
        Question(21609, "Quelle dynastie a régné le plus longtemps en France ?", listOf("Les Capétiens", "Les Bourbons", "Les Valois", "Les Mérovingiens"), 0, "Histoire", Difficulty.HARD, explanation = "Les Capétiens ont régné sans interruption de 987 à 1792, puis de 1814 à 1830, soit plus de 800 ans, ce qui en fait la plus longue dynastie de France."),
        Question(21610, "En quelle année l'homme a-t-il marché sur la Lune ?", listOf("1969", "1967", "1971", "1965"), 0, "Histoire", Difficulty.EASY, explanation = "La mission Apollo 11 de la NASA a permis aux astronautes Neil Armstrong et Buzz Aldrin de poser le pied sur la Lune le 20 juillet 1969."),
        Question(21611, "Quelle route commerciale reliait l'Europe à l'Asie ?", listOf("La Route de la Soie", "La Route des Épices", "La Route du Thé", "La Route de l'Or"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La Route de la Soie était un réseau de routes terrestres et maritimes reliant la Chine à la Méditerranée, permettant les échanges de soie, d'épices et d'autres marchandises entre l'Europe et l'Asie."),
        Question(21614, "En quelle année l'URSS s'est-elle effondrée ?", listOf("1991", "1989", "1993", "1985"), 0, "Histoire", Difficulty.MEDIUM, explanation = "L'URSS s'est officiellement dissoute le 26 décembre 1991, suite à la démission de Mikhaïl Gorbatchev et à la déclaration d'indépendance de plusieurs républiques."),
        Question(21615, "Quelle invention Gutenberg a-t-il révolutionné ?", listOf("L'imprimerie à caractères mobiles", "La machine à écrire", "Le télégraphe", "Le papier"), 0, "Histoire", Difficulty.EASY, explanation = "Gutenberg a perfectionné l'imprimerie en Europe en mettant au point des caractères mobiles en métal, permettant une reproduction rapide et économique des textes."),
        Question(21616, "Quel pharaon a régné le plus longtemps en Égypte ?", listOf("Ramsès II (66 ans)", "Khéops", "Toutankhamon", "Cléopâtre"), 0, "Histoire", Difficulty.HARD, explanation = "Ramsès II a régné environ 66 ans, de 1279 à 1213 av. J.-C., ce qui en fait le pharaon au règne le plus long de l'histoire égyptienne."),
        Question(21619, "Qui a été le dernier tsar de Russie ?", listOf("Nicolas II", "Alexandre III", "Pierre le Grand", "Ivan le Terrible"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Nicolas II a été le dernier empereur de Russie, régnant de 1894 jusqu'à son abdication forcée en 1917 pendant la Révolution de Février."),
        Question(21620, "En quelle année la bombe atomique a-t-elle été larguée sur Hiroshima ?", listOf("1945", "1944", "1943", "1946"), 0, "Histoire", Difficulty.EASY, explanation = "Les États-Unis ont largué la bombe atomique sur Hiroshima le 6 août 1945, pendant la Seconde Guerre mondiale, précipitant la capitulation du Japon."),
        Question(21621, "Quel peuple a construit Angkor Wat ?", listOf("Les Khmers", "Les Thaïs", "Les Birmans", "Les Vietnamiens"), 0, "Histoire", Difficulty.HARD, explanation = "Angkor Wat a été construit au XIIe siècle sous le règne du roi khmer Suryavarman II, servant de temple hindou dédié à Vishnu."),
        Question(21622, "Qui a unifié l'Italie au XIXe siècle ?", listOf("Giuseppe Garibaldi et Cavour", "Napoléon", "Mazzini seul", "Victor Emmanuel seul"), 0, "Histoire", Difficulty.HARD, explanation = "Giuseppe Garibaldi et Camillo Cavour ont joué des rôles clés dans le Risorgimento, le mouvement d'unification italienne. Cavour, en tant que Premier ministre du Piémont-Sardaigne, a mené les efforts diplomatiques, tandis que Garibaldi a conquis le sud avec ses Chemises rouges."),
        Question(21623, "Quelle guerre a opposé le Nord et le Sud des États-Unis ?", listOf("La guerre de Sécession (1861-1865)", "La guerre d'Indépendance", "La guerre de 1812", "La guerre hispano-américaine"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La guerre de Sécession a éclaté en 1861 suite à la sécession des États esclavagistes du Sud, opposés à l'abolition de l'esclavage prônée par le Nord industrialisé."),
        Question(21625, "En quelle année la Déclaration d'indépendance américaine a-t-elle été signée ?", listOf("1776", "1789", "1770", "1783"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le 4 juillet 1776, le Second Congrès continental a adopté la Déclaration d'indépendance, proclamant la séparation des treize colonies américaines de la Grande-Bretagne.")
    )

    // ===== CULTURE GÉNÉRALE — 30 questions =====
    private fun culture(): List<Question> = listOf(
        Question(21701, "Combien de couleurs a l'arc-en-ciel ?", listOf("7", "5", "6", "8"), 0, "Culture", Difficulty.EASY, explanation = "L'arc-en-ciel est traditionnellement décrit avec sept couleurs : rouge, orange, jaune, vert, bleu, indigo et violet. Cette classification a été popularisée par Isaac Newton."),
        Question(21702, "Quel est le symbole de la paix ?", listOf("La colombe", "L'aigle", "Le lion", "L'ours"), 0, "Culture", Difficulty.EASY, explanation = "La colombe est devenue un symbole universel de la paix depuis le récit biblique de l'arche de Noé, où elle apporta un rameau d'olivier pour annoncer la fin du déluge."),
        Question(21703, "Combien de merveilles du monde antique existe-t-il ?", listOf("7", "5", "10", "12"), 0, "Culture", Difficulty.EASY, explanation = "La liste canonique des sept merveilles du monde antique a été établie par des auteurs grecs comme Philon de Byzance, incluant des chefs-d'œuvre comme la pyramide de Khéops ou le phare d'Alexandrie."),
        Question(21704, "Quel jeu de société se joue sur un plateau de 64 cases ?", listOf("Les échecs", "Les dames", "Le go", "Le backgammon"), 0, "Culture", Difficulty.EASY, explanation = "Le plateau de 64 cases est spécifique au jeu d'échecs, qui se joue sur un échiquier de 8 cases sur 8."),
        Question(21705, "Quelle langue est la plus parlée au monde (en nombre de locuteurs natifs) ?", listOf("Le mandarin", "L'anglais", "L'espagnol", "L'hindi"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le mandarin est la langue maternelle de plus d'un milliard de personnes, principalement en Chine, ce qui en fait la langue la plus parlée au monde en nombre de locuteurs natifs."),
        Question(21706, "Quel peintre a coupé sa propre oreille ?", listOf("Vincent van Gogh", "Paul Gauguin", "Claude Monet", "Pablo Picasso"), 0, "Culture", Difficulty.EASY, explanation = "Vincent van Gogh s'est coupé l'oreille gauche en 1888 après une dispute avec Paul Gauguin, un épisode marquant de ses troubles mentaux."),
        Question(21707, "Combien de signes du zodiaque y a-t-il ?", listOf("12", "10", "8", "14"), 0, "Culture", Difficulty.EASY, explanation = "Le zodiaque occidental compte 12 signes, correspondant aux 12 constellations traversées par le Soleil au cours de l'année. Cette division remonte à l'astronomie babylonienne antique."),
        Question(21708, "Quel monument se trouve à Agra, en Inde ?", listOf("Le Taj Mahal", "Le Lotus Temple", "Le Fort Rouge", "Le Palais des Vents"), 0, "Culture", Difficulty.EASY, explanation = "Le Taj Mahal est un mausolée de marbre blanc construit au XVIIe siècle par l'empereur moghol Shah Jahan en mémoire de son épouse Mumtaz Mahal. Il est situé à Agra, en Inde."),
        Question(21709, "Quel artiste a peint 'La Nuit étoilée' ?", listOf("Vincent van Gogh", "Claude Monet", "Paul Cézanne", "Pierre-Auguste Renoir"), 0, "Culture", Difficulty.EASY, explanation = "Vincent van Gogh a peint 'La Nuit étoilée' en 1889 alors qu'il était interné à l'asile de Saint-Rémy-de-Provence, représentant la vue depuis sa fenêtre."),
        Question(21710, "Quel est l'alphabet utilisé en Russie ?", listOf("L'alphabet cyrillique", "L'alphabet latin", "L'alphabet grec", "L'alphabet arabe"), 0, "Culture", Difficulty.EASY, explanation = "Le cyrillique est l'alphabet officiel de la Russie, dérivé du grec byzantin et créé par les saints Cyrille et Méthode au IXe siècle."),
        Question(21711, "Combien de lettres comporte l'alphabet français ?", listOf("26", "24", "28", "30"), 0, "Culture", Difficulty.EASY, explanation = "L'alphabet français standard compte 26 lettres, comme l'alphabet latin dont il est issu, bien qu'il inclut aussi des lettres diacritées comme le é ou le ç."),
        Question(21712, "Quel peuple a inventé le zéro ?", listOf("Les Indiens (civilisation indienne)", "Les Arabes", "Les Grecs", "Les Babyloniens"), 0, "Culture", Difficulty.HARD, explanation = "Le concept du zéro comme nombre et comme chiffre a été développé par les mathématiciens indiens, notamment dans la civilisation de la vallée de l'Indus et les textes védiques."),
        Question(21713, "Quel instrument mesure les tremblements de terre ?", listOf("Le sismographe", "Le baromètre", "Le thermomètre", "L'anémomètre"), 0, "Culture", Difficulty.EASY, explanation = "Le sismographe enregistre les mouvements du sol provoqués par les ondes sismiques, permettant ainsi de détecter et de mesurer l'intensité des tremblements de terre."),
        Question(21714, "Quel designer a créé la robe 'petite robe noire' iconique ?", listOf("Coco Chanel", "Christian Dior", "Yves Saint Laurent", "Givenchy"), 0, "Culture", Difficulty.MEDIUM, explanation = "Coco Chanel a révolutionné la mode féminine en 1926 en introduisant la petite robe noire, sobre et élégante, qui contrastait avec les tenues colorées et corsetées de l'époque."),
        Question(21715, "Combien de cartes contient un jeu de tarot de Marseille ?", listOf("78", "52", "56", "22"), 0, "Culture", Difficulty.HARD, explanation = "Le tarot de Marseille se compose de 78 cartes : 56 arcanes mineurs (quatre séries de 14 cartes) et 22 arcanes majeurs (atouts)."),
        Question(21716, "Quel architecte a conçu la Sagrada Família ?", listOf("Antoni Gaudí", "Le Corbusier", "Frank Lloyd Wright", "Renzo Piano"), 0, "Culture", Difficulty.MEDIUM, explanation = "Antoni Gaudí a dirigé la construction de la Sagrada Família à Barcelone à partir de 1883, en y intégrant son style moderniste unique. L'édifice, toujours inachevé, est l'une de ses œuvres les plus emblématiques."),
        Question(21717, "Quelle couleur obtient-on en mélangeant du bleu et du jaune ?", listOf("Du vert", "Du orange", "Du violet", "Du marron"), 0, "Culture", Difficulty.EASY, explanation = "Le vert est une couleur secondaire obtenue par la synthèse additive ou soustractive du bleu et du jaune, un principe de base en théorie des couleurs."),
        Question(21719, "Combien de faces a un dodécaèdre ?", listOf("12", "10", "20", "8"), 0, "Culture", Difficulty.HARD, explanation = "Le dodécaèdre est un solide géométrique composé de 12 faces pentagonales régulières, d'où son nom issu du grec \"dodeka\" (douze) et \"hedra\" (face)."),
        Question(21720, "Quel célèbre tableau est exposé au Louvre derrière une vitre blindée ?", listOf("La Joconde", "La Liberté guidant le peuple", "Le Radeau de la Méduse", "Les Noces de Cana"), 0, "Culture", Difficulty.EASY, explanation = "La Joconde, peinte par Léonard de Vinci, est protégée par une vitre blindée au Louvre en raison de sa valeur inestimable et pour la préserver des tentatives de vandalisme."),
        Question(21721, "Quel est le jour le plus long de l'année dans l'hémisphère nord ?", listOf("Le solstice d'été (~21 juin)", "Le solstice d'hiver", "L'équinoxe de printemps", "L'équinoxe d'automne"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le solstice d'été marque le moment où l'axe de la Terre est le plus incliné vers le Soleil, offrant ainsi le maximum d'heures d'ensoleillement dans l'hémisphère nord."),
        Question(21722, "Quel animal est le symbole de la France ?", listOf("Le coq", "L'aigle", "Le lion", "L'ours"), 0, "Culture", Difficulty.EASY, explanation = "Le coq gaulois est un symbole historique de la France, dérivant du jeu de mots latin entre \"gallus\" (coq) et \"Gallus\" (Gaulois). Il figure sur les pièces de monnaie et les maillots de l'équipe de France de football."),
        Question(21723, "Combien de planètes du système solaire ont des anneaux ?", listOf("4 (Jupiter, Saturne, Uranus, Neptune)", "1 (Saturne)", "2", "3"), 0, "Culture", Difficulty.HARD, explanation = "Les quatre planètes gazeuses géantes du système solaire possèdent des anneaux : Jupiter, Saturne, Uranus et Neptune. Saturne est la plus célèbre pour ses anneaux visibles, mais les autres ont des systèmes d'anneaux plus fins et moins brillants."),
        Question(21724, "Quel pays a la plus grande population musulmane ?", listOf("L'Indonésie", "L'Arabie saoudite", "Le Pakistan", "L'Égypte"), 0, "Culture", Difficulty.HARD, explanation = "L'Indonésie, avec plus de 230 millions de musulmans, est le pays comptant la plus grande communauté musulmane au monde, bien que l'islam soit né au Moyen-Orient."),
        Question(21725, "Quel est le plus vieux sport connu de l'humanité ?", listOf("La lutte", "La course à pied", "La natation", "Le tir à l'arc"), 0, "Culture", Difficulty.HARD, explanation = "Des fresques égyptiennes vieilles de 5000 ans représentent déjà des combats de lutte, ce qui en fait le sport le plus ancien dont on ait des traces écrites et visuelles."),
        Question(21726, "Quel mouvement artistique est associé à Andy Warhol ?", listOf("Le Pop Art", "Le cubisme", "L'impressionnisme", "Le surréalisme"), 0, "Culture", Difficulty.MEDIUM, explanation = "Andy Warhol est une figure centrale du Pop Art, mouvement qui a émergé dans les années 1950-1960 en utilisant des images de la culture de masse et de la consommation."),
        Question(21727, "Combien de dents de lait un enfant a-t-il ?", listOf("20", "24", "16", "28"), 0, "Culture", Difficulty.EASY, explanation = "Un enfant possède 20 dents de lait, qui commencent généralement à apparaître vers l'âge de 6 mois et tombent progressivement pour laisser place aux dents définitives."),
        Question(21728, "Quel est le métal le plus précieux en joaillerie ?", listOf("Le platine", "L'or", "L'argent", "Le palladium"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le platine est plus rare que l'or et plus résistant à l'usure, ce qui en fait le métal le plus précieux en joaillerie haut de gamme."),
        Question(21729, "Quel est le signe astrologique du mois de mars ?", listOf("Poissons et Bélier", "Verseau et Poissons", "Bélier et Taureau", "Capricorne et Verseau"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le mois de mars chevauche deux signes astrologiques : les Poissons jusqu'au 20 mars environ, puis le Bélier à partir du 21 mars."),
        Question(21730, "Quelle danse argentine est inscrite au patrimoine immatériel de l'UNESCO ?", listOf("Le tango", "La salsa", "La samba", "Le flamenco"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le tango argentin a été inscrit en 2009 sur la liste représentative du patrimoine culturel immatériel de l'humanité par l'UNESCO.")
    )

    // ===== MATHÉMATIQUES — 30 questions =====
    private fun mathematiques(): List<Question> = listOf(
        Question(21801, "Combien vaut Pi arrondi à 2 décimales ?", listOf("3,14", "3,16", "3,12", "3,18"), 0, "Mathématiques", Difficulty.EASY, explanation = "Pi est le rapport constant entre la circonférence d'un cercle et son diamètre, et sa valeur tronquée à deux décimales est 3,14."),
        Question(21803, "Combien vaut la racine carrée de 144 ?", listOf("12", "14", "11", "13"), 0, "Mathématiques", Difficulty.EASY, explanation = "12 est la racine carrée de 144 car 12 multiplié par lui-même donne 144."),
        Question(21805, "Combien de faces a un cube ?", listOf("6", "4", "8", "12"), 0, "Mathématiques", Difficulty.EASY, explanation = "Un cube possède 6 faces car c'est un polyèdre régulier composé de six carrés identiques. Chaque face est un côté plat de cette figure géométrique tridimensionnelle."),
        Question(21806, "Qu'est-ce qu'une suite de Fibonacci ?", listOf("Chaque terme est la somme des deux précédents", "Chaque terme double le précédent", "Une suite géométrique", "Une suite de nombres premiers"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "Leonardo Fibonacci introduisit cette suite en 1202 dans son ouvrage Liber Abaci. Chaque nombre est obtenu en additionnant les deux précédents, débutant généralement par 0 et 1."),
        Question(21807, "Combien vaut 2 puissance 10 ?", listOf("1024", "512", "2048", "256"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "2 puissance 10 signifie multiplier 2 par lui-même 10 fois, ce qui donne 1024, une valeur clé en informatique pour le kilooctet."),
        Question(21808, "Quelle est la formule de l'aire d'un cercle ?", listOf("π × r²", "2 × π × r", "π × d", "r² × 2"), 0, "Mathématiques", Difficulty.EASY, explanation = "L'aire d'un cercle se calcule en multipliant le nombre π (environ 3,14) par le carré du rayon (r²). Cette formule découle de la relation entre le rayon et la surface du disque."),
        Question(21809, "Qu'est-ce qu'un nombre imaginaire ?", listOf("Un nombre dont le carré est négatif (i² = -1)", "Un nombre très grand", "Un nombre qui n'existe pas", "Un nombre décimal infini"), 0, "Mathématiques", Difficulty.HARD, explanation = "En mathématiques, les nombres réels ne permettent pas de résoudre des équations comme x² = -1. Les nombres imaginaires, basés sur l'unité i où i² = -1, étendent le système numérique pour inclure ces solutions."),
        Question(21810, "Combien vaut la factorielle de 5 (5!) ?", listOf("120", "60", "24", "720"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "5! = 5 × 4 × 3 × 2 × 1 = 120, la factorielle d'un entier positif étant le produit de tous les entiers de 1 à ce nombre."),
        Question(21811, "Qu'est-ce que le nombre d'or ?", listOf("~1,618 (phi)", "~2,718 (e)", "~3,14 (pi)", "~1,414 (√2)"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "Le nombre d'or, noté φ (phi), est une constante mathématique irrationnelle approximativement égale à 1,618, souvent retrouvée dans les proportions esthétiques en art et en architecture."),
        Question(21812, "Quel mathématicien a inventé la géométrie analytique ?", listOf("René Descartes", "Blaise Pascal", "Pierre de Fermat", "Gottfried Leibniz"), 0, "Mathématiques", Difficulty.HARD, explanation = "René Descartes a publié en 1637 La Géométrie, où il introduit l'usage des coordonnées pour lier algèbre et géométrie, fondant ainsi la géométrie analytique."),
        Question(21813, "Combien de sommets a un icosaèdre ?", listOf("12", "20", "10", "8"), 0, "Mathématiques", Difficulty.EXPERT, explanation = "Un icosaèdre est un polyèdre régulier composé de 20 faces triangulaires. Il possède 12 sommets où se rencontrent cinq triangles."),
        Question(21814, "Qu'est-ce qu'une matrice ?", listOf("Un tableau rectangulaire de nombres", "Un type d'équation", "Un graphique", "Un algorithme"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "En mathématiques, une matrice est un tableau rectangulaire organisé en lignes et colonnes, utilisé pour représenter des données ou des transformations linéaires."),
        Question(21815, "Quel est le plus petit nombre premier ?", listOf("2", "1", "3", "0"), 0, "Mathématiques", Difficulty.EASY, explanation = "2 est le plus petit nombre premier car il n'est divisible que par 1 et par lui-même, et il est le seul nombre pair à posséder cette propriété."),
        Question(21816, "Qu'est-ce que l'intégrale en mathématiques ?", listOf("Le calcul de l'aire sous une courbe", "La pente d'une droite", "La dérivée d'une fonction", "Un type de fraction"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "L'intégrale mesure l'aire entre une courbe et l'axe horizontal, en additionnant des surfaces infinitésimales. C'est un outil fondamental du calcul différentiel et intégral."),
        Question(21817, "Combien vaut log₁₀(1000) ?", listOf("3", "10", "100", "30"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "Le logarithme décimal de 1000 est 3 car 10³ = 1000."),
        Question(21818, "Qu'est-ce que le dernier théorème de Fermat ?", listOf("aⁿ + bⁿ = cⁿ n'a pas de solution entière pour n > 2", "La somme des angles = 180°", "Tout nombre pair est somme de deux premiers", "Il existe une infinité de nombres premiers"), 0, "Mathématiques", Difficulty.EXPERT, explanation = "Énoncé par Pierre de Fermat au XVIIe siècle, ce théorème affirme qu'aucun triplet d'entiers positifs ne vérifie aⁿ + bⁿ = cⁿ pour n > 2, démontré seulement en 1994 par Andrew Wiles."),
        Question(21819, "Quel est le périmètre d'un cercle de rayon r ?", listOf("2πr", "πr²", "πd²", "r²"), 0, "Mathématiques", Difficulty.EASY, explanation = "Le périmètre d'un cercle, aussi appelé circonférence, se calcule en multipliant le diamètre (2r) par π, ce qui donne 2πr."),
        Question(21820, "Combien de diagonales a un hexagone ?", listOf("9", "6", "12", "3"), 0, "Mathématiques", Difficulty.HARD, explanation = "Un hexagone a 6 sommets. Le nombre de diagonales se calcule par la formule n(n-3)/2, soit 6*3/2 = 9."),
        Question(21821, "Qu'est-ce qu'une fonction exponentielle ?", listOf("f(x) = eˣ", "f(x) = x²", "f(x) = ln(x)", "f(x) = 1/x"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "La fonction exponentielle f(x) = eˣ est la fonction dont la dérivée est égale à elle-même, et où e est la constante mathématique valant environ 2,718."),
        Question(21822, "Quel mathématicien a prouvé le dernier théorème de Fermat en 1995 ?", listOf("Andrew Wiles", "Pierre de Fermat", "Leonhard Euler", "Carl Gauss"), 0, "Mathématiques", Difficulty.EXPERT, explanation = "Andrew Wiles a démontré le dernier théorème de Fermat en 1995, résolvant une conjecture vieille de plus de 350 ans grâce à la preuve de la conjecture de Shimura-Taniyama-Weil pour les courbes elliptiques semi-stables."),
        Question(21823, "Combien vaut la somme des angles d'un triangle ?", listOf("180°", "360°", "90°", "270°"), 0, "Mathématiques", Difficulty.EASY, explanation = "La somme des angles intérieurs d'un triangle dans la géométrie euclidienne est toujours égale à 180 degrés, une propriété démontrée par Euclide."),
        Question(21824, "Qu'est-ce qu'un vecteur ?", listOf("Une grandeur ayant direction, sens et norme", "Un nombre négatif", "Un type de matrice", "Une droite infinie"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "En mathématiques et en physique, un vecteur modélise une quantité qui ne peut être décrite uniquement par sa valeur numérique, car elle nécessite une orientation dans l'espace, comme une force ou une vitesse."),
        Question(21825, "Quel est le volume d'une sphère ?", listOf("4/3 × π × r³", "π × r²", "2 × π × r", "4 × π × r²"), 0, "Mathématiques", Difficulty.HARD, explanation = "Cette formule a été établie par Archimède dans l'Antiquité, qui a démontré que le volume d'une sphère équivaut aux deux tiers du volume du cylindre qui la circonscrit."),
        Question(21826, "Qu'est-ce que la conjecture de Goldbach ?", listOf("Tout nombre pair > 2 est somme de deux nombres premiers", "Il existe une infinité de jumeaux premiers", "P ≠ NP", "π est transcendant"), 0, "Mathématiques", Difficulty.EXPERT, explanation = "Formulée en 1742 par Christian Goldbach dans une lettre à Euler, cette conjecture mathématique reste non démontrée à ce jour, bien qu'elle ait été vérifiée pour tous les nombres pairs jusqu'à 4×10^18."),
        Question(21827, "Combien vaut cos(0) ?", listOf("1", "0", "-1", "π"), 0, "Mathématiques", Difficulty.EASY, explanation = "Le cosinus de 0 degré (ou 0 radian) est égal à 1 car, sur le cercle trigonométrique, le point correspondant à cet angle a pour coordonnées (1, 0)."),
        Question(21828, "Qu'est-ce qu'une asymptote ?", listOf("Une droite dont une courbe se rapproche sans jamais l'atteindre", "Un type de triangle", "Une équation sans solution", "Un nombre irrationnel"), 0, "Mathématiques", Difficulty.MEDIUM, explanation = "En mathématiques, une asymptote est une droite que la courbe d'une fonction approche indéfiniment sans jamais la toucher, utilisée pour décrire le comportement limite d'une fonction à l'infini ou près d'un point."),
        Question(21829, "Quel est le symbole de l'infini en mathématiques ?", listOf("∞", "Ω", "Σ", "∆"), 0, "Mathématiques", Difficulty.EASY, explanation = "Le symbole ∞, appelé lemniscate, a été introduit par le mathématicien John Wallis en 1655. Il représente un concept d'une quantité sans limite.")
